  it('rejects on file not found', async () => {
    server.use(
      http.post(`${BASE}/api/files/info`, () =>
        HttpResponse.json({ detail: 'File not found' }, { status: 404 })
      )
    );

    await expect(getFileInfo('msc://profile/missing.txt')).rejects.toMatchObject({
      response: { status: 404 },
    });
