  it('rejects on permission denied', async () => {
    server.use(
      http.post(`${BASE}/api/files/info`, () =>
        HttpResponse.json({ detail: 'Permission denied' }, { status: 403 })
      )
    );

    await expect(getFileInfo('msc://restricted/file.txt')).rejects.toMatchObject({
      response: { status: 403 },
    });
